class Solution:
    def twoSum(self, numbers: list[int], target: int) -> list[int]:
        keep_track_idx = {}
        for idx in range(len(numbers)):
            if numbers[idx] not in keep_track_idx: keep_track_idx[numbers[idx]] = [idx+1]
            else: keep_track_idx[numbers[idx]].append(idx+1)

        numbers = list(set(numbers))
        possibles = []
        for elem in numbers[::-1]:
            does_exist = target - elem
            if does_exist in numbers: possibles.append(tuple(sorted([elem, does_exist])))
            else: numbers.remove(elem)

        def length_is_1(possibles):
            left = list(set(possibles))[0][0]
            right = list(set(possibles))[0][1]
            res = []
            if left != right: res.append((keep_track_idx[left][0], keep_track_idx[right][0]))
            else: res.append((keep_track_idx[possibles[0][0]]))
            return list(res[0])

        if len(set(numbers)) == 2: return length_is_1(possibles)
        else:
            possibles = list(set(possibles))
            for elem in possibles:
                a,b = elem
                if a == b and len(keep_track_idx[a]) == 1:
                    possibles.remove(elem)
            return length_is_1(possibles)


